import sys
import os

def render_template(template_path, output_path):
    with open(template_path, 'r', encoding='utf-8') as template_file:
        template = template_file.read()

    key_value_pairs = {}
    for line in sys.stdin:
        line = line.strip()
        if '=' in line:
            key, value = line.split('=', 1)
            key_value_pairs[key] = value

    rendered = []
    i = 0
    n = len(template)
    while i < n:
        if template[i] == '{' and i + 1 < n and template[i+1] == '{':
            i += 2
            start = i
            while i < n and template[i] != '}':
                i += 1
            if i < n and template[i] == '}':
                key = template[start:i]
                rendered.append(key_value_pairs.get(key, ''))
                i += 1
        else:
            rendered.append(template[i])
            i += 1

    output = ''.join(rendered)
    with open(output_path, 'w', encoding='utf-8') as output_file:
        output_file.write(output)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python render.py TEMPLATE_PATH OUTPUT_PATH", file=sys.stderr)
        sys.exit(1)
    render_template(sys.argv[1], sys.argv[2])

import sys
import os

def main():
    stdin_lines = sys.stdin.read().splitlines()
    variables = {}

    for line in stdin_lines:
        if '=' in line:
            key, value = line.split('=', 1)
            variables[key.strip()] = value.strip()

    if len(sys.argv) != 3:
        sys.exit(1)

    template_path = sys.argv[1]
    output_path = sys.argv[2]

    with open(template_path, 'r', encoding='utf-8') as template_file:
        template_content = template_file.read()

    rendered_content = []
    i = 0
    while i < len(template_content):
        if template_content.startswith('{{', i):
            j = template_content.find('}}', i)
            if j == -1:
                rendered_content.append(template_content[i:])
                break
            key = template_content[i+2:j]
            rendered_content.append(variables.get(key, ''))
            i = j + 2
        else:
            rendered_content.append(template_content[i])
            i += 1

    with open(output_path, 'w', encoding='utf-8') as output_file:
        output_file.write(''.join(rendered_content))

if __name__ == '__main__':
    main()
